# ─── merilv.migrations.0007_recover_plant_org_mappings ──────────────────────
def _recover_plant_org_mappings(apps, schema_editor):
    LegacyPlantOrgMapping = apps.get_model("merilv", "LegacyPlantOrgMapping")
    PlantMaster = apps.get_model("merilv", "PlantMaster")
    OrganizationMaster = apps.get_model("merilv", "OrganizationMaster")
    PlantOrgMapping = apps.get_model("merilv", "PlantOrgMapping")

    plants = set(PlantMaster.objects.values_list("plant_code", flat=True))
    orgs = set(OrganizationMaster.objects.values_list("org_code", flat=True))

    recovered = []
    seen: set[tuple[str, str]] = set()
    claimed_primary: set[str] = set()

    for legacy in LegacyPlantOrgMapping.objects.all().order_by("-is_primary", "legacy_id"):
        plant_code = (legacy.plant_code or "").strip()
        org_code = (legacy.org_code or "").strip()
        if plant_code not in plants or org_code not in orgs:
            continue
        key = (plant_code, org_code)
        if key in seen:
            continue
        seen.add(key)

        is_primary = bool(legacy.is_primary) and plant_code not in claimed_primary
        if is_primary:
            claimed_primary.add(plant_code)

        recovered.append(
            PlantOrgMapping(
                plant_id=plant_code,
                organization_id=org_code,
                is_primary=is_primary,
                created_at=legacy.created_at,
            )
        )

    backfilled = []
    mapped_plants = {plant for plant, _ in seen}
    for plant_code, org_code in PlantMaster.objects.exclude(organization__isnull=True).values_list(
        "plant_code", "organization_id"
    ):
        if plant_code in mapped_plants or org_code not in orgs:
            continue
        backfilled.append(
            PlantOrgMapping(plant_id=plant_code, organization_id=org_code, is_primary=True)
        )

    if recovered:
        PlantOrgMapping.objects.bulk_create(recovered, ignore_conflicts=True)
    if backfilled:
        PlantOrgMapping.objects.bulk_create(backfilled, ignore_conflicts=True)

    for plant_code in {plant for plant, _ in seen} - claimed_primary:
        first = (
            PlantOrgMapping.objects.filter(plant_id=plant_code)
            .order_by("organization_id")
            .first()
        )
        if first is not None:
            first.is_primary = True
            first.save(update_fields=["is_primary"])

    total = len(recovered) + len(backfilled)
    if total:
        print(
            f"\n  PlantOrgMapping: recovered {len(recovered)} legacy row(s), "
            f"backfilled {len(backfilled)} from PlantMaster.organization."
        )


def _discard_plant_org_mappings(apps, schema_editor):
    apps.get_model("merilv", "PlantOrgMapping").objects.all().delete()


