def _merge_duplicate_finishes(apps, schema_editor):
    from django.db.models import Count

    FinishedDelivery = apps.get_model("merilv", "FinishedDelivery")
    groups = (
        FinishedDelivery.objects.values("session_id", "delivery_no")
        .annotate(n=Count("id"))
        .filter(n__gt=1)
    )
    for group in groups:
        rows = list(
            FinishedDelivery.objects.filter(
                session_id=group["session_id"], delivery_no=group["delivery_no"]
            ).order_by("pk")
        )
        keeper, duplicates = rows[0], rows[1:]
        changed = []
        for duplicate in duplicates:
            for field in _TEXT_FIELDS:
                if not getattr(keeper, field) and getattr(duplicate, field):
                    setattr(keeper, field, getattr(duplicate, field))
                    changed.append(field)
            if not keeper.box_count and duplicate.box_count:
                keeper.box_count = duplicate.box_count
                changed.append("box_count")
            if keeper.weight_kg is None and duplicate.weight_kg is not None:
                keeper.weight_kg = duplicate.weight_kg
                changed.append("weight_kg")
            if keeper.status == "pending_courier" and duplicate.status == "complete":
                keeper.status = "complete"
                changed.append("status")
            if duplicate.is_partial and not keeper.is_partial:
                keeper.is_partial = True
                changed.append("is_partial")
        if changed:
            keeper.save(update_fields=sorted(set(changed)))
        FinishedDelivery.objects.filter(pk__in=[duplicate.pk for duplicate in duplicates]).delete()


