# ── Ported from 0004_dispatched_serial_ledger ─────────────────────────────
def backfill_from_finished_deliveries(apps, schema_editor):
    """Seed the ledger from deliveries that were finished before it existed.

    Without this the guarantee would only start from today: every serial
    already shipped would be free for the next upload to reuse, which is the
    exact failure the ledger is being added to prevent.

    Ordered oldest-finish-first so that where two finished deliveries somehow
    carry the same serial — possible precisely because nothing stopped it
    before now — the earliest dispatch owns it and the later one is skipped.
    Deduped in Python rather than leaning on ``ignore_conflicts``, so the row
    that survives is chosen rather than whichever the database happened to
    insert first.
    """
    FinishedDelivery = apps.get_model("merilv", "FinishedDelivery")
    DispatchedSerial = apps.get_model("merilv", "DispatchedSerial")
    OutboundScan = apps.get_model("merilv", "OutboundScan")

    seen: set[str] = set()
    rows = []
    finished = (
        FinishedDelivery.objects.exclude(session__isnull=True)
        .order_by("created_at", "pk")
        .values("pk", "session_id", "delivery_no", "entity_id", "picker_id")
    )
    for record in finished:
        scans = OutboundScan.objects.filter(
            session_id=record["session_id"], line__delivery_no=record["delivery_no"],
        ).values("serial_identity", "material", "batch")
        for scan in scans:
            serial = (scan["serial_identity"] or "").strip()
            if not serial or serial in seen:
                continue
            seen.add(serial)
            rows.append(
                DispatchedSerial(
                    serial=serial,
                    entity_id=record["entity_id"],
                    finished_delivery_id=record["pk"],
                    delivery_no=record["delivery_no"],
                    material=scan["material"] or "",
                    batch=scan["batch"] or "",
                    dispatched_by_id=record["picker_id"],
                )
            )
    if rows:
        DispatchedSerial.objects.bulk_create(rows, batch_size=1000)


def drop_backfill(apps, schema_editor):
    """Reverse leg. The table is dropped by the CreateModel reversal anyway;
    this exists so the migration is reversible without a special case."""
    apps.get_model("merilv", "DispatchedSerial").objects.all().delete()


# ── Ported from 0006_close_fully_shipped_sessions ─────────────────────────
def _fully_shipped(apps):
    """(session_pk, …) for every active session whose dump is fully finished."""
    OutboundSession = apps.get_model("merilv", "OutboundSession")
    FinishedDelivery = apps.get_model("merilv", "FinishedDelivery")
    DeliveryLine = apps.get_model("merilv", "DeliveryLine")

    done = []
    sessions = OutboundSession.objects.exclude(dump__isnull=True).only("pk", "dump_id", "status")
    for session in sessions.iterator():
        wanted = {
            no
            for no in DeliveryLine.objects.filter(dump_id=session.dump_id)
            .values_list("delivery_no", flat=True)
            if no
        }
        if not wanted:
            continue
        finished = set(
            FinishedDelivery.objects.filter(session_id=session.pk).values_list(
                "delivery_no", flat=True
            )
        )
        if not (wanted - finished):
            done.append(session.pk)
    return done


def close_finished_sessions(apps, schema_editor):
    OutboundSession = apps.get_model("merilv", "OutboundSession")
    pks = [
        pk
        for pk in _fully_shipped(apps)
        if OutboundSession.objects.filter(pk=pk, status="active").exists()
    ]
    if pks:
        OutboundSession.objects.filter(pk__in=pks).update(status="completed")


def reopen_finished_sessions(apps, schema_editor):
    OutboundSession = apps.get_model("merilv", "OutboundSession")
    pks = [
        pk
        for pk in _fully_shipped(apps)
        if OutboundSession.objects.filter(pk=pk, status="completed").exists()
    ]
    if pks:
        OutboundSession.objects.filter(pk__in=pks).update(status="active")


